def build_public_ops_head_injection():
    state = get_search_ops_runtime_state()
    fragments = ["<!-- traderhub-ops-head -->"]
    if state["google_site_verification"]:
        fragments.append(
            f'<meta name="google-site-verification" content="{html_lib.escape(state["google_site_verification"], quote=True)}">'
        )
    if state["bing_site_verification"]:
        fragments.append(
            f'<meta name="msvalidate.01" content="{html_lib.escape(state["bing_site_verification"], quote=True)}">'
        )
    if state["ga4_measurement_id"]:
        ga4_id = html_lib.escape(state["ga4_measurement_id"], quote=True)
        fragments.extend(
            [
                f'<script async src="https://www.googletagmanager.com/gtag/js?id={ga4_id}"></script>',
                "<script>",
                "window.dataLayer = window.dataLayer || [];",
                "function gtag(){dataLayer.push(arguments);}",
                "gtag('js', new Date());",
                f"gtag('config', '{ga4_id}', {{ send_page_view: true }});",
                "window.traderhubTrackEvent = function(eventName, eventParams) {",
                "  if (typeof gtag === 'function' && eventName) {",
                "    gtag('event', eventName, eventParams || {});",
                "  }",
                "};",
                "</script>",
            ]
        )
    if state["adsense_client"]:
        adsense_client = html_lib.escape(state["adsense_client"], quote=True)
        fragments.append(
            f'<script async data-ad-client="{adsense_client}" src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client={adsense_client}" crossorigin="anonymous"></script>'
        )
    if len(fragments) == 1:
        return ""
    return "\n".join(fragments)


def get_public_ad_runtime_state():
    runtime = get_runtime_config()
    return {
        "adsense_client": str(runtime.get("ADSENSE_CLIENT") or "").strip(),
        "adsense_slot_inline": str(runtime.get("ADSENSE_SLOT_INLINE") or "").strip(),
        "adsense_slot_sidebar": str(runtime.get("ADSENSE_SLOT_SIDEBAR") or "").strip(),
        "adsense_slot_vertical": str(runtime.get("ADSENSE_SLOT_VERTICAL") or "").strip(),
        "sponsor_name": str(runtime.get("SPONSOR_NAME") or "").strip(),
        "sponsor_label": str(runtime.get("SPONSOR_LABEL") or "Sponsored").strip() or "Sponsored",
        "sponsor_copy": str(runtime.get("SPONSOR_COPY") or "").strip(),
        "sponsor_url": str(runtime.get("SPONSOR_URL") or "").strip(),
        "sponsor_cta": str(runtime.get("SPONSOR_CTA") or "Visit Sponsor").strip() or "Visit Sponsor",
        "sponsor_image_url": str(runtime.get("SPONSOR_IMAGE_URL") or "").strip(),
        "sponsor_embed_html": str(runtime.get("SPONSOR_EMBED_HTML") or "").strip(),
    }


def build_adsense_slot_html(slot_id, layout_hint="auto"):
    state = get_public_ad_runtime_state()
    adsense_client = state["adsense_client"]
    slot_value = str(slot_id or "").strip()
    if not adsense_client or not slot_value:
        return ""
    layout_attr = ' data-ad-layout="in-article"' if layout_hint == "in-article" else ""
    return (
        f'<ins class="adsbygoogle" style="display:block" data-ad-client="{html_lib.escape(adsense_client, quote=True)}" '
        f'data-ad-slot="{html_lib.escape(slot_value, quote=True)}" data-ad-format="auto" '
        f'data-full-width-responsive="true"{layout_attr}></ins>'
        "<script>(adsbygoogle = window.adsbygoogle || []).push({});</script>"
    )


def build_public_ad_context(page_title, page_family="public"):
    state = get_public_ad_runtime_state()
    sponsor_name = state["sponsor_name"] or "Featured Partner"
    sponsor_copy = state["sponsor_copy"] or (
        f"{page_title} is supported by a direct sponsor placement. Keep sponsor messages separate from TraderHub's editorial research and use your own judgment before acting."
    )
    sponsor_ad = None
    if state["sponsor_url"] or state["sponsor_embed_html"] or state["sponsor_copy"] or state["sponsor_name"]:
        sponsor_ad = {
            "label": state["sponsor_label"],
            "name": sponsor_name,
            "copy": sponsor_copy,
            "url": state["sponsor_url"],
            "cta": state["sponsor_cta"],
            "image_url": state["sponsor_image_url"],
            "embed_html": state["sponsor_embed_html"],
            "disclaimer": "Paid sponsor placement. TraderHub editorial views stay separate.",
        }
    google_inline_ad_html = build_adsense_slot_html(state["adsense_slot_inline"], layout_hint="in-article")
    google_sidebar_ad_html = build_adsense_slot_html(state["adsense_slot_sidebar"], layout_hint="auto")
    google_vertical_ad_html = build_adsense_slot_html(state["adsense_slot_vertical"], layout_hint="auto")
    return {
        "ad_page_family": page_family,
        "sponsor_ad": sponsor_ad,
        "google_inline_ad_html": google_inline_ad_html,
        "google_sidebar_ad_html": google_sidebar_ad_html,
        "google_vertical_ad_html": google_vertical_ad_html,
        "adsense_ready": bool(state["adsense_client"]),
    }


def send_telegram_message(message_text, chat_id=None):
    creds = get_active_telegram_credentials()
    token = creds["token"]
    target_chat_id = str(chat_id or creds["chat_id"] or "").strip()
    if not token or not target_chat_id:
        raise ValueError("Telegram token or chat ID is missing in .env.")
    response = requests.post(
        f"https://api.telegram.org/bot{token}/sendMessage",
        json={
            "chat_id": target_chat_id,
            "text": message_text,
            "disable_web_page_preview": True,
        },
        timeout=20,
    )
    response.raise_for_status()
    return response.json()


def persist_env_value(env_key, env_value):
    if not ENV_PATH.exists():
        ENV_PATH.write_text(f"{env_key}={env_value}\n", encoding="utf-8")
        return

    lines = ENV_PATH.read_text(encoding="utf-8").splitlines()
    replaced = False
    updated_lines = []
    for line in lines:
        if line.startswith(f"{env_key}="):
            updated_lines.append(f"{env_key}={env_value}")
            replaced = True
        else:
            updated_lines.append(line)
    if not replaced:
        updated_lines.append(f"{env_key}={env_value}")
    ENV_PATH.write_text("\n".join(updated_lines) + "\n", encoding="utf-8")


def build_upstox_login_url(state="traderhub-upstox"):
    creds = get_active_upstox_credentials()
    query = urllib.parse.urlencode(
        {
            "client_id": creds["client_id"],
            "redirect_uri": creds["redirect_uri"],
            "response_type": "code",
            "state": state,
        }
    )
    return f"{creds['api_base_url']}/login/authorization/dialog?{query}"


def exchange_upstox_code_for_token(authorization_code):
    creds = get_active_upstox_credentials()
    response = requests.post(
        f"{creds['api_base_url']}/login/authorization/token",
        headers={
            "accept": "application/json",
            "Api-Version": "2.0",
            "Content-Type": "application/x-www-form-urlencoded",
        },
        data={
            "code": authorization_code,
            "client_id": creds["client_id"],
            "client_secret": creds["client_secret"],
            "redirect_uri": creds["redirect_uri"],
            "grant_type": "authorization_code",
        },
        timeout=20,
    )
    response.raise_for_status()
    return response.json()


def upstox_api_get(path, params=None, access_token=None):
    creds = get_active_upstox_credentials()
    token = access_token or creds["access_token"]
    if not token:
        raise ValueError("Upstox access token is missing.")
    response = requests.get(
        f"{creds['api_base_url'].rstrip('/')}/{path.lstrip('/')}",
        headers={
            "accept": "application/json",
            "Api-Version": "2.0",
            "Authorization": f"Bearer {token}",
        },
        params=params or {},
        timeout=20,
    )
    response.raise_for_status()
    return response.json()


def parse_numeric_text(value):
    text = str(value or "").strip()
    if not text:
        return None
    cleaned = text.replace(",", "").replace("%", "").replace("Rs.", "").replace("INR", "").strip()
    try:
        return float(cleaned)
    except ValueError:
        return None


def find_upstox_history_entry(history_rows):
    history_rows = history_rows or []
    for entry in history_rows:
        if entry.get("value") not in (None, ""):
            return entry
    return history_rows[0] if history_rows else None


def get_upstox_profile_metric_display(profile_data, candidate_keys):
    profile_data = profile_data or {}
    for key in candidate_keys:
        value = profile_data.get(key)
        if value in (None, ""):
            continue
        if isinstance(value, dict):
            formatted = value.get("formatted")
            if formatted not in (None, ""):
                return str(formatted)
            inner_value = value.get("value")
            unit = value.get("unit")
            if inner_value not in (None, "") and unit:
                return f"{inner_value} {unit}"
            if inner_value not in (None, ""):
                return str(inner_value)
        return str(value)
    return None


def get_upstox_nested_metric_display(payload, candidate_keys):
    normalized_candidates = {str(item or "").strip().lower() for item in candidate_keys}
    seen_objects = set()

    def walk(node):
        node_id = id(node)
        if node_id in seen_objects:
            return None
        seen_objects.add(node_id)

        if isinstance(node, dict):
            for key, value in node.items():
                if str(key or "").strip().lower() in normalized_candidates:
                    if isinstance(value, dict):
                        formatted = value.get("formatted")
                        if formatted not in (None, ""):
                            return str(formatted)
                        inner_value = value.get("value")
                        unit = value.get("unit")
                        if inner_value not in (None, "") and unit:
                            return f"{inner_value} {unit}"
                        if inner_value not in (None, ""):
                            return str(inner_value)
                    elif value not in (None, ""):
                        return str(value)
                nested_match = walk(value)
                if nested_match not in (None, ""):
                    return nested_match
        elif isinstance(node, list):
            for item in node:
                nested_match = walk(item)
                if nested_match not in (None, ""):
                    return nested_match
        return None

    return walk(payload)


def get_upstox_ratio_row(ratio_map, candidate_names):
    ratio_map = ratio_map or {}
    for candidate in candidate_names:
        row = ratio_map.get(str(candidate or "").strip().upper())
        if row:
            return row
    for key, row in ratio_map.items():
        upper_key = str(key or "").strip().upper()
        if "DEBT" in upper_key and "EQUITY" in upper_key:
            return row
    return {}


def get_upstox_balance_sheet_bundle(isin, time_period="yearly"):
    balance_payload = upstox_api_get(
        f"/fundamentals/{isin}/balance-sheet",
        params={"type": "consolidated", "fs": "true", "time_period": time_period},
    )
    return (balance_payload or {}).get("data") or {}


def get_upstox_income_statement_bundle(isin, time_period="yearly"):
    income_payload = upstox_api_get(
        f"/fundamentals/{isin}/income-statement",
        params={"type": "consolidated", "time_period": time_period},
    )
    return ((income_payload or {}).get("data") or {}).get("income_statement") or []


def get_upstox_cash_flow_bundle(isin, time_period="yearly"):
    cash_flow_payload = upstox_api_get(
        f"/fundamentals/{isin}/cash-flow",
        params={"type": "consolidated", "time_period": time_period},
    )
    payload_data = (cash_flow_payload or {}).get("data") or {}
    if isinstance(payload_data, dict):
        return payload_data.get("cash_flow") or payload_data.get("cashflow") or payload_data.get("cash_flow_statement") or []
    return []


def get_upstox_statement_value(statement_map, candidate_labels):
    if not statement_map:
        return None, ""
    normalized_map = {str(key or "").strip().upper(): value for key, value in statement_map.items()}
    for label in candidate_labels:
        row = normalized_map.get(str(label or "").strip().upper())
        if not row:
            continue
        entry = find_upstox_history_entry((row or {}).get("history"))
        numeric_value = parse_numeric_text((entry or {}).get("value"))
        if numeric_value is not None:
            return numeric_value, (entry or {}).get("period") or ""
    return None, ""


def get_upstox_nested_metric_numeric(payload, candidate_keys):
    normalized_candidates = {str(item or "").strip().lower() for item in candidate_keys}
    seen_objects = set()

    def walk(node):
        node_id = id(node)
        if node_id in seen_objects:
            return None
        seen_objects.add(node_id)

        if isinstance(node, dict):
            for key, value in node.items():
                if str(key or "").strip().lower() in normalized_candidates:
                    if isinstance(value, dict):
                        formatted_value = parse_numeric_text(value.get("value"))
                        if formatted_value is not None:
                            return formatted_value
                        nested_value = parse_numeric_text(value.get("formatted"))
                        if nested_value is not None:
                            return nested_value
                    else:
                        numeric_value = parse_numeric_text(value)
                        if numeric_value is not None:
                            return numeric_value
                nested_match = walk(value)
                if nested_match is not None:
                    return nested_match
        elif isinstance(node, list):
            for item in node:
                nested_match = walk(item)
                if nested_match is not None:
                    return nested_match
        return None

    return walk(payload)


def collect_upstox_nested_numeric_values(payload, candidate_keys):
    normalized_candidates = {str(item or "").strip().lower() for item in candidate_keys}
    seen_objects = set()
    collected = []

    def walk(node):
        node_id = id(node)
        if node_id in seen_objects:
            return
        seen_objects.add(node_id)

        if isinstance(node, dict):
            for key, value in node.items():
                if str(key or "").strip().lower() in normalized_candidates:
                    if isinstance(value, dict):
                        numeric_value = parse_numeric_text(value.get("value"))
                        if numeric_value is None:
                            numeric_value = parse_numeric_text(value.get("formatted"))
                    else:
                        numeric_value = parse_numeric_text(value)
                    if numeric_value is not None:
                        collected.append(numeric_value)
                walk(value)
        elif isinstance(node, list):
            for item in node:
                walk(item)

    walk(payload)
    return collected


def get_upstox_latest_income_value(income_rows, category_names):
    row_map = {str(row.get("category") or "").strip().lower(): row for row in (income_rows or [])}
    for category_name in category_names:
        row = row_map.get(str(category_name or "").strip().lower())
        if not row:
            continue
        entry = find_upstox_history_entry((row.get("history") or []))
        numeric_value = parse_numeric_text((entry or {}).get("value"))
        if numeric_value is not None:
            return numeric_value, (entry or {}).get("period") or "", entry
    return None, "", {}


def build_upstox_screener_snapshot(fundamentals_bundle, reference_price_numeric=None, period_price_lookup=None):
    fundamentals_bundle = fundamentals_bundle or {}
    profile_data = fundamentals_bundle.get("profile") or {}
    ratio_rows = fundamentals_bundle.get("key_ratios") or []
    income_rows = fundamentals_bundle.get("income_statement") or []
    balance_sheet_data = fundamentals_bundle.get("balance_sheet") or {}
    ratio_map = {str(row.get("name") or "").strip().upper(): row for row in ratio_rows}
    statement_map = {
        str(row.get("particular") or "").strip().upper(): row
        for row in ((balance_sheet_data or {}).get("full_statement") or [])
    }
    profile_market_cap_inr = parse_numeric_text(
        get_upstox_profile_metric_display(
            profile_data,
            [
                "company_market_cap_inr",
                "market_cap_inr",
                "market_cap",
                "market_capitalisation",
                "market_capitalization",
            ],
        )
        or get_upstox_nested_metric_display(
            profile_data,
            [
                "company_market_cap_inr",
                "market_cap_inr",
                "market_cap",
                "market_capitalisation",
                "market_capitalization",
            ],
        )
    )

    equity_capital_value, equity_capital_period = get_upstox_statement_value(
        statement_map,
        ["EQUITY SHARE CAPITAL", "EQUITY CAPITAL", "SHARE CAPITAL", "ISSUED SHARE CAPITAL"],
    )
    preference_dividend_value, _ = get_upstox_statement_value(
        statement_map,
        ["PREFERENCE DIVIDEND", "DIVIDEND ON PREFERENCE SHARES"],
    )
    pat_value, pat_period, _ = get_upstox_latest_income_value(
        income_rows,
        ["net_profit", "profit_after_tax", "pat"],
    )

    face_value = get_upstox_nested_metric_numeric(
        profile_data,
        ["face_value", "face value", "fv", "par_value", "par value"],
    )
    shares_issued = get_upstox_nested_metric_numeric(
        profile_data,
        [
            "shares_outstanding",
            "outstanding_shares",
            "total_shares",
            "total_equity_shares",
            "number_of_equity_shares",
            "number_of_shares",
            "issued_shares",
            "equity_shares_outstanding",
        ],
    )
    if shares_issued in (None, 0) and equity_capital_value not in (None, 0) and face_value not in (None, 0):
        shares_issued = (equity_capital_value * 10000000.0) / face_value
    if shares_issued in (None, 0) and profile_market_cap_inr not in (None, 0) and reference_price_numeric not in (None, 0):
        shares_issued = profile_market_cap_inr / reference_price_numeric
    if face_value in (None, 0) and equity_capital_value not in (None, 0) and shares_issued not in (None, 0):
        try:
            inferred_face_value = (equity_capital_value * 10000000.0) / shares_issued
        except ZeroDivisionError:
            inferred_face_value = None
        if inferred_face_value and inferred_face_value > 0:
            face_value = inferred_face_value

    preference_dividend_value = preference_dividend_value or 0.0
    eps_value = None
    if pat_value is not None and shares_issued not in (None, 0):
        eps_value = (pat_value - preference_dividend_value) * 10000000.0 / shares_issued

    pe_value = None
    if reference_price_numeric not in (None, 0) and eps_value not in (None, 0):
        pe_value = reference_price_numeric / eps_value

    market_cap_inr = None
    if reference_price_numeric not in (None, 0) and shares_issued not in (None, 0):
        market_cap_inr = reference_price_numeric * shares_issued

    period_price_numeric = None
    if callable(period_price_lookup) and pat_period:
        try:
            period_price_numeric = period_price_lookup(pat_period)
        except Exception:
            period_price_numeric = None
    if period_price_numeric in (None, 0):
        period_price_numeric = reference_price_numeric

    dividend_yield_ratio = parse_numeric_text(
        (get_upstox_ratio_row(ratio_map, ["DIVIDEND YIELD", "DIV YIELD", "DIVIDEND YIELD %"]) or {}).get("company_value")
    )
    annual_dividend_per_share = get_upstox_nested_metric_numeric(
        fundamentals_bundle,
        [
            "annual_dividend_per_share",
            "dividend_per_share",
            "last_financial_year_dividend_per_share",
            "fy_dividend_per_share",
            "annual_dividend",
        ],
    )
    if annual_dividend_per_share in (None, 0) and dividend_yield_ratio not in (None, 0) and period_price_numeric not in (None, 0):
        annual_dividend_per_share = period_price_numeric * (dividend_yield_ratio / 100.0)

    dividend_yield_pct = None
    if annual_dividend_per_share not in (None, 0) and period_price_numeric not in (None, 0):
        dividend_yield_pct = (annual_dividend_per_share / period_price_numeric) * 100.0

    quarterly_dividend_values = collect_upstox_nested_numeric_values(
        fundamentals_bundle,
        [
            "quarterly_dividend_amount",
            "quarter_dividend_amount",
            "quarterly_dividend_per_share",
            "qtrly_dividend_amount",
            "latest_quarter_dividend",
            "interim_dividend_per_share",
            "final_dividend_per_share",
            "special_dividend_per_share",
        ],
    )
    quarterly_dividend_amount = round(sum(quarterly_dividend_values), 2) if quarterly_dividend_values else None
    if market_cap_inr in (None, 0) and profile_market_cap_inr not in (None, 0):
        market_cap_inr = profile_market_cap_inr

    if pe_value in (None, 0):
        pe_value = parse_numeric_text((get_upstox_ratio_row(ratio_map, ["P/E", "PE RATIO"]) or {}).get("company_value"))

    if dividend_yield_pct in (None, 0):
        dividend_yield_pct = parse_numeric_text(
            (get_upstox_ratio_row(ratio_map, ["DIVIDEND YIELD", "DIV YIELD", "DIVIDEND YIELD %"]) or {}).get("company_value")
        )

    return {
        "shares_issued": shares_issued,
        "equity_capital_value": equity_capital_value,
        "equity_capital_period": equity_capital_period,
        "face_value": face_value,
        "pat_value": pat_value,
        "pat_period": pat_period,
        "preference_dividend_value": preference_dividend_value,
        "eps_value": eps_value,
        "pe_value": pe_value,
        "market_cap_inr": market_cap_inr,
        "market_cap_display": format_crore_display(market_cap_inr / 10000000.0) if market_cap_inr not in (None, 0) else "Source Pending",
        "period_price_numeric": period_price_numeric,
        "annual_dividend_per_share": annual_dividend_per_share,
        "dividend_yield_pct": dividend_yield_pct,
        "quarterly_dividend_amount": quarterly_dividend_amount,
    }


def get_upstox_fundamentals_bundle(isin):
    profile_payload = upstox_api_get(f"/fundamentals/{isin}/profile")
    key_ratios_payload = upstox_api_get(f"/fundamentals/{isin}/key-ratios")
    holdings_payload = upstox_api_get(f"/fundamentals/{isin}/share-holdings")
    balance_sheet_data = {}
    quarterly_income_rows = []
    cash_flow_rows = []
    try:
        balance_sheet_data = get_upstox_balance_sheet_bundle(isin)
    except Exception:
        balance_sheet_data = {}
    try:
        quarterly_income_rows = get_upstox_income_statement_bundle(isin, time_period="quarterly")
    except Exception:
        quarterly_income_rows = []
    try:
        cash_flow_rows = get_upstox_cash_flow_bundle(isin, time_period="yearly")
    except Exception:
        cash_flow_rows = []
    return {
        "profile": (profile_payload or {}).get("data") or {},
        "key_ratios": (key_ratios_payload or {}).get("data") or [],
        "income_statement": get_upstox_income_statement_bundle(isin, time_period="yearly"),
        "quarterly_income_statement": quarterly_income_rows,
        "share_holdings": (holdings_payload or {}).get("data") or [],
        "balance_sheet": balance_sheet_data,
        "cash_flow": cash_flow_rows,
    }


def build_upstox_financial_sections(isin, symbol, last_price_numeric):
    financial_metrics = build_placeholder_financial_metrics("General")
    holdings_deals = build_placeholder_holdings_deals(symbol)
    ownership_watch_rows = build_placeholder_ownership_watch()
    market_cap_display = "Source Pending"
    sector_override = None
    note = ""

    if not isin:
        return financial_metrics, holdings_deals, ownership_watch_rows, market_cap_display, sector_override, "ISIN is not available yet for fundamentals mapping."

    try:
        fundamentals_bundle = get_upstox_fundamentals_bundle(isin)
    except requests.RequestException as exc:
        response_text = exc.response.text if exc.response is not None else str(exc)
        return financial_metrics, holdings_deals, ownership_watch_rows, market_cap_display, sector_override, f"Upstox fundamentals request failed: {response_text}"
    except Exception as exc:
        return financial_metrics, holdings_deals, ownership_watch_rows, market_cap_display, sector_override, f"Upstox fundamentals mapping failed: {exc}"

    profile_data = fundamentals_bundle.get("profile") or {}
    ratio_rows = fundamentals_bundle.get("key_ratios") or []
    income_rows = fundamentals_bundle.get("income_statement") or []
    holdings_rows = fundamentals_bundle.get("share_holdings") or []
    balance_sheet_data = fundamentals_bundle.get("balance_sheet") or {}

    ratio_map = {str(row.get("name") or "").strip().upper(): row for row in ratio_rows}
    income_map = {str(row.get("category") or "").strip().lower(): row for row in income_rows}
    holdings_map = {str(row.get("category") or "").strip().lower(): row for row in holdings_rows}
    debt_equity_row = get_upstox_ratio_row(ratio_map, ["DEBT/EQUITY", "DEBT / EQUITY", "DEBT TO EQUITY"])
    debt_equity_value = (debt_equity_row or {}).get("company_value")
    balance_history = (balance_sheet_data or {}).get("history") or []
    balance_entry = find_upstox_history_entry(balance_history)
    total_assets_value = parse_numeric_text((balance_entry or {}).get("total_asset"))
    total_liabilities_value = parse_numeric_text((balance_entry or {}).get("total_liability"))
    shareholder_equity_value = None
    if total_assets_value is not None and total_liabilities_value is not None:
        shareholder_equity_value = total_assets_value - total_liabilities_value

    full_statement_rows = (balance_sheet_data or {}).get("full_statement") or []
    statement_map = {str(row.get("particular") or "").strip().upper(): row for row in full_statement_rows}
    total_borrowings_value, total_borrowings_period = get_upstox_statement_value(
        statement_map,
        [
            "TOTAL BORROWINGS",
            "BORROWINGS",
            "TOTAL DEBT",
            "FINANCIAL LIABILITIES - BORROWINGS",
        ],
    )
    if total_borrowings_value is None:
        current_borrowings_value, current_borrowings_period = get_upstox_statement_value(
            statement_map,
            [
                "CURRENT BORROWINGS",
                "SHORT TERM BORROWINGS",
                "SHORT-TERM BORROWINGS",
                "CURRENT FINANCIAL LIABILITIES - BORROWINGS",
            ],
        )
        non_current_borrowings_value, non_current_borrowings_period = get_upstox_statement_value(
            statement_map,
            [
                "NON-CURRENT BORROWINGS",
                "LONG TERM BORROWINGS",
                "LONG-TERM BORROWINGS",
                "NON CURRENT BORROWINGS",
                "NON-CURRENT FINANCIAL LIABILITIES - BORROWINGS",
            ],
        )
        if current_borrowings_value is not None or non_current_borrowings_value is not None:
            total_borrowings_value = (current_borrowings_value or 0.0) + (non_current_borrowings_value or 0.0)
            total_borrowings_period = current_borrowings_period or non_current_borrowings_period
    if debt_equity_value in (None, "") and total_borrowings_value is not None and shareholder_equity_value not in (None, 0):
        debt_equity_value = f"{(total_borrowings_value / shareholder_equity_value):.2f}"

    revenue_entry = find_upstox_history_entry((income_map.get("revenue") or {}).get("history"))
    operating_profit_entry = find_upstox_history_entry((income_map.get("operating_profit") or {}).get("history"))
    net_profit_entry = find_upstox_history_entry((income_map.get("net_profit") or {}).get("history"))

    revenue_latest = parse_numeric_text((revenue_entry or {}).get("value"))
    operating_profit_latest = parse_numeric_text((operating_profit_entry or {}).get("value"))
    operating_margin_value = None
    if revenue_latest and operating_profit_latest is not None and revenue_latest != 0:
        operating_margin_value = (operating_profit_latest / revenue_latest) * 100

    roe_value = (ratio_map.get("ROE") or {}).get("company_value")
    roce_value = (ratio_map.get("ROCE") or {}).get("company_value")
    pb_numeric = parse_numeric_text((ratio_map.get("P/B") or {}).get("company_value"))
    screener_snapshot = build_upstox_screener_snapshot(fundamentals_bundle, reference_price_numeric=last_price_numeric)
    market_cap_display = screener_snapshot.get("market_cap_display") or "Source Pending"
    eps_value = screener_snapshot.get("eps_value")
    pe_numeric = screener_snapshot.get("pe_value")
    shares_issued = screener_snapshot.get("shares_issued")

    book_value = None
    if shareholder_equity_value not in (None, 0) and shares_issued not in (None, 0):
        book_value = (shareholder_equity_value * 10000000.0) / shares_issued
    elif pb_numeric and pb_numeric > 0 and last_price_numeric and last_price_numeric > 0:
        book_value = last_price_numeric / pb_numeric

    financial_metrics = [
        {
            "label": "Sales Growth",
            "value": (revenue_entry or {}).get("change") or "Source Pending",
            "subtext": f"Latest yearly revenue move: {(revenue_entry or {}).get('period') or 'Period pending'}.",
        },
        {
            "label": "Profit Growth",
            "value": (net_profit_entry or {}).get("change") or "Source Pending",
            "subtext": f"Latest yearly net profit move: {(net_profit_entry or {}).get('period') or 'Period pending'}.",
        },
        {
            "label": "ROE",
            "value": roe_value or "Source Pending",
            "subtext": f"Sector benchmark: {(ratio_map.get('ROE') or {}).get('sector_value') or 'Pending'}.",
        },
        {
            "label": "ROCE",
            "value": roce_value or "Source Pending",
            "subtext": f"Sector benchmark: {(ratio_map.get('ROCE') or {}).get('sector_value') or 'Pending'}.",
        },
        {
            "label": "Book Value",
            "value": format_price(book_value) if book_value is not None else "Source Pending",
            "subtext": (
                "Computed from shareholder equity and issued equity shares."
                if book_value is not None and shares_issued not in (None, 0) and shareholder_equity_value not in (None, 0)
                else "Per-share book value is waiting on a cleaner equity-share mapping."
            ),
        },
        {
            "label": "EPS (TTM)",
            "value": format_price(eps_value) if eps_value is not None else "Source Pending",
            "subtext": "Calculated from the last financial year PAT minus preference dividend, divided by issued equity shares.",
        },
        {
            "label": "Operating Margin",
            "value": f"{operating_margin_value:.2f}%" if operating_margin_value is not None else "Source Pending",
            "subtext": "Computed from latest operating profit and revenue history when available.",
        },
    ]
    if debt_equity_value:
        financial_metrics.insert(
            4,
            {
                "label": "Debt / Equity",
                "value": debt_equity_value,
                "subtext": (
                    f"Sector benchmark: {(debt_equity_row or {}).get('sector_value') or 'Pending'}."
                    if (debt_equity_row or {}).get("sector_value")
                    else (
                        f"Derived from detailed borrowings and equity for {total_borrowings_period}."
                        if total_borrowings_value is not None and shareholder_equity_value not in (None, 0)
                        else "Leverage snapshot from the current fundamentals source."
                    )
                ),
            },
        )

    def latest_holding_details(category_names):
        for category_name in category_names:
            history = (holdings_map.get(category_name) or {}).get("history") or []
            entry = find_upstox_history_entry(history)
            if entry and entry.get("value") is not None:
                previous_entry = history[1] if len(history) >= 2 and history[1].get("value") is not None else None
                current_numeric = parse_numeric_text(entry.get("value"))
                previous_numeric = parse_numeric_text((previous_entry or {}).get("value"))
                delta_display = "Pending"
                if current_numeric is not None and previous_numeric is not None:
                    delta_display = f"{current_numeric - previous_numeric:+.2f} pp"
                return {
                    "value": f"{entry.get('value')}%",
                    "period": entry.get("period") or "Latest quarter",
                    "previous_value": (f"{previous_entry.get('value')}%" if previous_entry and previous_entry.get("value") is not None else "Pending"),
                    "previous_period": (previous_entry.get("period") or "Previous quarter") if previous_entry else "Previous quarter pending",
                    "delta": delta_display,
                }
        return {
            "value": "Source Pending",
            "period": "Quarterly holding source pending.",
            "previous_value": "Pending",
            "previous_period": "Previous quarter pending",
            "delta": "Pending",
        }

    promoter_details = latest_holding_details(["promoters", "promoter"])
    fii_details = latest_holding_details(["fii", "foreign_institutional_investors"])
    dii_details = latest_holding_details(["dii", "other_dii", "domestic_institutional_investors"])
    mutual_fund_details = latest_holding_details(["mutual_funds", "mutual fund"])
    retail_other_details = latest_holding_details(["retail_and_other", "retail", "public"])
    pledge_details = latest_holding_details(["pledged", "pledge", "promoter_pledge", "pledged_shares"])

    holdings_deals = [
        {"label": "Promoter Holding", "value": promoter_details["value"], "note": promoter_details["period"]},
        {"label": "FII Holding", "value": fii_details["value"], "note": fii_details["period"]},
        {"label": "DII Holding", "value": dii_details["value"], "note": dii_details["period"]},
        {"label": "Mutual Fund Holding", "value": mutual_fund_details["value"], "note": mutual_fund_details["period"]},
        {"label": "Retail & Other", "value": retail_other_details["value"], "note": retail_other_details["period"]},
        {"label": "Block / Bulk Deal Watch", "value": "Source Pending", "note": "Deals feed is still reserved for the next source integration."},
    ]
    if pledge_details["value"] != "Source Pending":
        holdings_deals.append(
            {
                "label": "Pledge",
                "value": pledge_details["value"],
                "note": pledge_details["period"],
            }
        )

    ownership_watch_rows = [
        {
            "category": "Promoter",
            "current": promoter_details["value"],
            "previous": promoter_details["previous_value"],
            "change": promoter_details["delta"],
            "note": f"{promoter_details['period']} vs {promoter_details['previous_period']}",
        },
        {
            "category": "FII",
            "current": fii_details["value"],
            "previous": fii_details["previous_value"],
            "change": fii_details["delta"],
            "note": f"{fii_details['period']} vs {fii_details['previous_period']}",
        },
        {
            "category": "DII",
            "current": dii_details["value"],
            "previous": dii_details["previous_value"],
            "change": dii_details["delta"],
            "note": f"{dii_details['period']} vs {dii_details['previous_period']}",
        },
        {
            "category": "Mutual Funds",
            "current": mutual_fund_details["value"],
            "previous": mutual_fund_details["previous_value"],
            "change": mutual_fund_details["delta"],
            "note": f"{mutual_fund_details['period']} vs {mutual_fund_details['previous_period']}",
        },
        {
            "category": "Retail & Other",
            "current": retail_other_details["value"],
            "previous": retail_other_details["previous_value"],
            "change": retail_other_details["delta"],
            "note": f"{retail_other_details['period']} vs {retail_other_details['previous_period']}",
        },
    ]

    sector_override = profile_data.get("sector")
    return financial_metrics, holdings_deals, ownership_watch_rows, market_cap_display, sector_override, note


def format_statement_cell(value, suffix=""):
    if value in (None, ""):
        return "-"
    if isinstance(value, str):
        text = value.strip()
        if text:
            return text
        return "-"
    if isinstance(value, (int, float)):
        if suffix == "%":
            return f"{value:.2f}%"
        if abs(float(value)) >= 1000:
            return f"{value:,.2f}".rstrip("0").rstrip(".")
        return f"{value:.2f}".rstrip("0").rstrip(".")
    return str(value)


def build_periodic_statement_table(raw_rows, row_defs, key_field="category", limit=8):
    row_map = {str(row.get(key_field) or "").strip().lower(): row for row in (raw_rows or [])}
    periods = []
    for row_def in row_defs:
        matched_row = None
        for candidate in row_def["candidates"]:
            matched_row = row_map.get(str(candidate or "").strip().lower())
            if matched_row:
                break
        if matched_row:
            periods = [str(item.get("period") or "").strip() for item in (matched_row.get("history") or []) if str(item.get("period") or "").strip()]
            if periods:
                break
    periods = periods[:limit]
    if not periods:
        return {"columns": [], "rows": [], "empty_message": "Source pending for this statement right now."}

    table_rows = []
    for row_def in row_defs:
        matched_row = None
        for candidate in row_def["candidates"]:
            matched_row = row_map.get(str(candidate or "").strip().lower())
            if matched_row:
                break
        history_map = {
            str(item.get("period") or "").strip(): item
            for item in (matched_row.get("history") or [])
            if str(item.get("period") or "").strip()
        } if matched_row else {}
        values = []
        for period in periods:
            entry = history_map.get(period) or {}
            raw_value = entry.get("value")
            numeric_value = parse_numeric_text(raw_value)
            display_value = format_statement_cell(numeric_value if numeric_value is not None else raw_value, row_def.get("suffix", ""))
            values.append(display_value)
        table_rows.append({"label": row_def["label"], "values": values})
    return {"columns": periods, "rows": table_rows, "empty_message": ""}


def build_shareholding_pattern_table(holdings_rows, limit=8):
    row_defs = [
        {"label": "Promoters", "candidates": ["promoters", "promoter"]},
        {"label": "FIIs", "candidates": ["fii", "foreign_institutional_investors"]},
        {"label": "DIIs", "candidates": ["dii", "other_dii", "domestic_institutional_investors"]},
        {"label": "Mutual Funds", "candidates": ["mutual_funds", "mutual fund"]},
        {"label": "Public / Retail", "candidates": ["retail_and_other", "retail", "public"]},
        {"label": "Pledged Shares", "candidates": ["pledged", "pledge", "promoter_pledge", "pledged_shares"]},
    ]
    row_map = {str(row.get("category") or "").strip().lower(): row for row in (holdings_rows or [])}
    periods = []
    for row_def in row_defs:
        matched_row = None
        for candidate in row_def["candidates"]:
            matched_row = row_map.get(str(candidate or "").strip().lower())
            if matched_row:
                break
        if matched_row:
            periods = [str(item.get("period") or "").strip() for item in (matched_row.get("history") or []) if str(item.get("period") or "").strip()]
            if periods:
                break
    periods = periods[:limit]
    if not periods:
        return {"columns": [], "rows": [], "empty_message": "Quarterly shareholding pattern is pending from the current fundamentals source."}

    pattern_rows = []
    for row_def in row_defs:
        matched_row = None
        for candidate in row_def["candidates"]:
            matched_row = row_map.get(str(candidate or "").strip().lower())
            if matched_row:
                break
        history_map = {
            str(item.get("period") or "").strip(): item
            for item in (matched_row.get("history") or [])
            if str(item.get("period") or "").strip()
        } if matched_row else {}
        values = []
        for period in periods:
            entry = history_map.get(period) or {}
            raw_value = entry.get("value")
            numeric_value = parse_numeric_text(raw_value)
            display_value = f"{numeric_value:.2f}%" if numeric_value is not None else (str(raw_value).strip() or "-")
            values.append(display_value)
        pattern_rows.append({"label": row_def["label"], "values": values})
    return {"columns": periods, "rows": pattern_rows, "empty_message": ""}


def build_stock_peer_comparison_row(symbol, company_name, last_price_numeric, fundamentals_bundle):
    ratio_rows = (fundamentals_bundle or {}).get("key_ratios") or []
    quarterly_income_rows = (fundamentals_bundle or {}).get("quarterly_income_statement") or []
    ratio_map = {str(row.get("name") or "").strip().upper(): row for row in ratio_rows}

    def get_latest_row_value(category_names, field="value"):
        row_map = {str(row.get("category") or "").strip().lower(): row for row in quarterly_income_rows}
        for category_name in category_names:
            row = row_map.get(str(category_name or "").strip().lower())
            if not row:
                continue
            history = row.get("history") or []
            if not history:
                continue
            entry = history[0]
            return entry.get(field), entry
        return None, {}

    screener_snapshot = build_upstox_screener_snapshot(fundamentals_bundle, reference_price_numeric=last_price_numeric)
    pe_value = screener_snapshot.get("pe_value")
    roce_value = parse_numeric_text((ratio_map.get("ROCE") or {}).get("company_value"))
    dividend_yield_value = screener_snapshot.get("dividend_yield_pct")
    market_cap_value = screener_snapshot.get("market_cap_inr")
    np_value, np_entry = get_latest_row_value(["net_profit", "profit_after_tax", "pat"])
    sales_value, sales_entry = get_latest_row_value(["revenue", "sales"])

    return {
        "company": company_name,
        "cmp": format_price(last_price_numeric) if last_price_numeric not in (None, 0) else "-",
        "pe": f"{pe_value:.2f}" if pe_value is not None else "-",
        "market_cap": format_crore_display(market_cap_value / 10000000.0) if market_cap_value is not None else "Source Pending",
        "dividend_yield": f"{dividend_yield_value:.2f}%" if dividend_yield_value is not None else "-",
        "np_qtr": format_statement_cell(np_value),
        "np_qtr_change": str((np_entry or {}).get("change") or "-"),
        "sales_qtr": format_statement_cell(sales_value),
        "sales_qtr_change": str((sales_entry or {}).get("change") or "-"),
        "roce": f"{roce_value:.2f}%" if roce_value is not None else "-",
    }


def build_upstox_stock_research_tables(isin, symbol, company_name, fundamentals_bundle=None):
    empty_table = {"columns": [], "rows": [], "empty_message": "Source pending right now."}
    fallback_links = [
        {
            "title": f"Official NSE announcements for {symbol}",
            "meta": "Exchange filings",
            "url": f"https://www.nseindia.com/companies-listing/corporate-filings-announcements?symbol={urllib.parse.quote(symbol)}&tabIndex=equity",
        },
        {
            "title": f"Official NSE corporate actions for {symbol}",
            "meta": "Dividend, split, bonus, rights",
            "url": f"https://www.nseindia.com/companies-listing/corporate-filings-actions?symbol={urllib.parse.quote(symbol)}&tabIndex=equity",
        },
    ]
    if not isin:
        return {
            "quarterly_results_table": dict(empty_table, empty_message="ISIN is pending, so quarterly statement data cannot be loaded yet."),
            "annual_profit_loss_table": empty_table,
            "balance_sheet_table": empty_table,
            "cash_flow_table": empty_table,
            "ratios_table": empty_table,
            "shareholding_pattern_table": dict(empty_table, empty_message="ISIN is pending, so shareholding trend data cannot be loaded yet."),
            "disclosure_links": fallback_links,
            "research_notes": ["ISIN mapping is still missing for this stock, so the deeper phase-2 research sections are waiting on fundamentals linkage."],
        }

    bundle = fundamentals_bundle or get_upstox_fundamentals_bundle(isin)
    profile_data = bundle.get("profile") or {}
    ratio_rows = bundle.get("key_ratios") or []
    yearly_income_rows = bundle.get("income_statement") or []
    quarterly_income_rows = bundle.get("quarterly_income_statement") or []
    holdings_rows = bundle.get("share_holdings") or []
    cash_flow_rows = bundle.get("cash_flow") or []
    balance_bundle = bundle.get("balance_sheet") or {}
    ratio_map = {str(row.get("name") or "").strip().upper(): row for row in ratio_rows}

    quarterly_results_table = build_periodic_statement_table(
        quarterly_income_rows,
        [
            {"label": "Sales", "candidates": ["revenue", "sales"]},
            {"label": "Expenses", "candidates": ["expenses", "total_expense", "operating_expense"]},
            {"label": "Operating Profit", "candidates": ["operating_profit", "ebitda", "operating_income"]},
            {"label": "OPM %", "candidates": ["operating_margin", "opm"]},
            {"label": "Other Income", "candidates": ["other_income"]},
            {"label": "Interest", "candidates": ["interest", "finance_cost"]},
            {"label": "Depreciation", "candidates": ["depreciation", "depreciation_and_amortization"]},
            {"label": "Profit Before Tax", "candidates": ["profit_before_tax", "pbt"]},
            {"label": "Tax %", "candidates": ["tax", "tax_expense", "tax_rate"], "suffix": "%"},
            {"label": "Net Profit", "candidates": ["net_profit", "profit_after_tax", "pat"]},
            {"label": "EPS", "candidates": ["eps", "earnings_per_share"]},
        ],
        limit=8,
    )
    annual_profit_loss_table = build_periodic_statement_table(
        yearly_income_rows,
        [
            {"label": "Sales", "candidates": ["revenue", "sales"]},
            {"label": "Expenses", "candidates": ["expenses", "total_expense", "operating_expense"]},
            {"label": "Operating Profit", "candidates": ["operating_profit", "ebitda", "operating_income"]},
            {"label": "OPM %", "candidates": ["operating_margin", "opm"]},
            {"label": "Other Income", "candidates": ["other_income"]},
            {"label": "Interest", "candidates": ["interest", "finance_cost"]},
            {"label": "Depreciation", "candidates": ["depreciation", "depreciation_and_amortization"]},
            {"label": "Profit Before Tax", "candidates": ["profit_before_tax", "pbt"]},
            {"label": "Tax %", "candidates": ["tax", "tax_expense", "tax_rate"], "suffix": "%"},
            {"label": "Net Profit", "candidates": ["net_profit", "profit_after_tax", "pat"]},
            {"label": "EPS", "candidates": ["eps", "earnings_per_share"]},
        ],
        limit=12,
    )
    balance_sheet_table = build_periodic_statement_table(
        (balance_bundle.get("full_statement") or []),
        [
            {"label": "Equity Capital", "candidates": ["EQUITY SHARE CAPITAL", "EQUITY CAPITAL", "SHARE CAPITAL"]},
            {"label": "Reserves", "candidates": ["RESERVES AND SURPLUS", "OTHER EQUITY", "RESERVES"]},
            {"label": "Borrowings", "candidates": ["TOTAL BORROWINGS", "BORROWINGS", "TOTAL DEBT"]},
            {"label": "Other Liabilities", "candidates": ["TOTAL LIABILITIES", "OTHER LIABILITIES", "NON-CURRENT LIABILITIES", "CURRENT LIABILITIES"]},
            {"label": "Total Liabilities", "candidates": ["TOTAL LIABILITIES AND EQUITY", "TOTAL LIABILITIES & EQUITY", "TOTAL EQUITY AND LIABILITIES"]},
            {"label": "Fixed Assets", "candidates": ["PROPERTY PLANT AND EQUIPMENT", "FIXED ASSETS", "NET BLOCK"]},
            {"label": "CWIP", "candidates": ["CAPITAL WORK IN PROGRESS", "CWIP"]},
            {"label": "Investments", "candidates": ["INVESTMENTS", "NON CURRENT INVESTMENTS", "CURRENT INVESTMENTS"]},
            {"label": "Other Assets", "candidates": ["OTHER ASSETS", "OTHER NON CURRENT ASSETS", "CURRENT ASSETS"]},
            {"label": "Total Assets", "candidates": ["TOTAL ASSETS"]},
        ],
        key_field="particular",
        limit=12,
    )
    cash_flow_table = build_periodic_statement_table(
        cash_flow_rows,
        [
            {"label": "Cash from Operating Activity", "candidates": ["cash_from_operating_activity", "operating_cash_flow", "cash_flow_from_operations"]},
            {"label": "Cash from Investing Activity", "candidates": ["cash_from_investing_activity", "investing_cash_flow"]},
            {"label": "Cash from Financing Activity", "candidates": ["cash_from_financing_activity", "financing_cash_flow"]},
            {"label": "Net Cash Flow", "candidates": ["net_cash_flow", "net_increase_in_cash"]},
            {"label": "Free Cash Flow", "candidates": ["free_cash_flow", "fcf"]},
            {"label": "CFO / OP", "candidates": ["cfo_op", "cash_flow_to_operating_profit"], "suffix": "%"},
        ],
        limit=12,
    )
    ratios_history_rows = []
    for row_name, label in [
        ("ROCE", "ROCE %"),
        ("ROE", "ROE %"),
        ("DEBT/EQUITY", "Debt / Equity"),
        ("CURRENT RATIO", "Current Ratio"),
        ("INTEREST COVERAGE", "Interest Coverage"),
    ]:
        ratio_row = ratio_map.get(row_name) or get_upstox_ratio_row(ratio_map, [row_name])
        if not ratio_row:
            continue
        histories = ratio_row.get("history") or []
        if not histories:
            continue
        if not ratios_history_rows:
            ratio_periods = [str(item.get("period") or "").strip() for item in histories if str(item.get("period") or "").strip()][:12]
        ratios_history_rows.append(
            {
                "label": label,
                "history": histories,
            }
        )
    if ratios_history_rows:
        ratios_table = {"columns": ratio_periods, "rows": [], "empty_message": ""}
        for item in ratios_history_rows:
            history_map = {str(entry.get("period") or "").strip(): entry for entry in item["history"] if str(entry.get("period") or "").strip()}
            values = []
            for period in ratio_periods:
                entry = history_map.get(period) or {}
                raw_value = entry.get("value") if "value" in entry else entry.get("company_value")
                numeric_value = parse_numeric_text(raw_value)
                if item["label"].endswith("%"):
                    display = f"{numeric_value:.2f}%" if numeric_value is not None else (str(raw_value).strip() or "-")
                else:
                    display = format_statement_cell(numeric_value if numeric_value is not None else raw_value)
                values.append(display)
            ratios_table["rows"].append({"label": item["label"], "values": values})
    else:
        ratios_table = dict(empty_table, empty_message="Ratio history is pending from the current fundamentals source.")

    shareholding_pattern_table = build_shareholding_pattern_table(holdings_rows, limit=8)
    website_url = str(profile_data.get("website") or profile_data.get("company_website") or "").strip()
    disclosure_links = []
    if website_url:
        disclosure_links.append({"title": f"{company_name} investor website", "meta": "Company website", "url": website_url})
    disclosure_links.extend(fallback_links)
    disclosure_links.append({"title": f"{company_name} annual reports", "meta": "Investor documents", "url": website_url or f"https://www.google.com/search?q={urllib.parse.quote(company_name + ' annual report investor relations')}"})
    disclosure_links.append({"title": f"{company_name} results and presentations", "meta": "Results / concalls / PPT", "url": website_url or f"https://www.google.com/search?q={urllib.parse.quote(company_name + ' results presentation investor relations')}"})
    research_notes = [
        "Quarterly and annual tables are sourced from the current fundamentals connector where available, and fall back cleanly when the source is thin.",
        "Peer comparison stays sector-first so users can judge valuation and quality in context, not in isolation.",
    ]
    return {
        "quarterly_results_table": quarterly_results_table,
        "annual_profit_loss_table": annual_profit_loss_table,
        "balance_sheet_table": balance_sheet_table,
        "cash_flow_table": cash_flow_table,
        "ratios_table": ratios_table,
        "shareholding_pattern_table": shareholding_pattern_table,
        "disclosure_links": disclosure_links,
        "research_notes": research_notes,
    }


def load_stock_isin_cache():
    if not STOCK_ISIN_CACHE_PATH.exists():
        return {}
    try:
        return json.loads(STOCK_ISIN_CACHE_PATH.read_text(encoding="utf-8"))
    except Exception:
        return {}


def save_stock_isin_cache(cache_map):
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    STOCK_ISIN_CACHE_PATH.write_text(json.dumps(cache_map, indent=2, sort_keys=True), encoding="utf-8")


def resolve_stock_isin(symbol, security_name=""):
    symbol = str(symbol or "").strip().upper()
    if not symbol:
        return ""

    master = load_symbol_master()
    master_row = master.get("by_symbol", {}).get(symbol) or {}
    master_isin = str(master_row.get("isin") or "").strip().upper()
    if master_isin:
        return master_isin

    cache_map = load_stock_isin_cache()
    cached_isin = str(cache_map.get(symbol) or "").strip().upper()
    if cached_isin:
        return cached_isin

    try:
        search_payload = upstox_api_get(
            "/instruments/search",
            params={
                "query": symbol,
                "exchanges": "NSE",
                "segments": "EQ",
                "page_number": 1,
                "records": 10,
            },
        )
    except Exception:
        return ""

    security_name = str(security_name or master_row.get("security") or "").strip().upper().rstrip(".")
    for item in (search_payload or {}).get("data") or []:
        trading_symbol = str(item.get("trading_symbol") or "").strip().upper()
        exchange = str(item.get("exchange") or "").strip().upper()
        item_isin = str(item.get("isin") or "").strip().upper()
        item_name = str(item.get("name") or "").strip().upper().rstrip(".")
        item_segment = str(item.get("segment") or "").strip().upper()
        if exchange == "NSE" and item_segment == "NSE_EQ" and trading_symbol == symbol and item_isin:
            if not security_name or item_name == security_name or security_name in item_name or item_name in security_name:
                cache_map[symbol] = item_isin
                save_stock_isin_cache(cache_map)
                return item_isin

    for item in (search_payload or {}).get("data") or []:
        trading_symbol = str(item.get("trading_symbol") or "").strip().upper()
        exchange = str(item.get("exchange") or "").strip().upper()
        item_isin = str(item.get("isin") or "").strip().upper()
        item_segment = str(item.get("segment") or "").strip().upper()
        if exchange == "NSE" and item_segment == "NSE_EQ" and trading_symbol == symbol and item_isin:
            cache_map[symbol] = item_isin
            save_stock_isin_cache(cache_map)
            return item_isin

    return ""


@lru_cache(maxsize=1)
def get_nse_instrument_map():
    client = build_kite_client(with_access_token=True)
    rows = client.instruments("NSE")
    instrument_map = {}

    for row in rows:
        symbol = str(row.get("tradingsymbol") or "").upper()
        if symbol:
            instrument_map[symbol] = row

    return instrument_map


@lru_cache(maxsize=1)
def get_nfo_instruments():
    client = build_kite_client(with_access_token=True)
    return client.instruments("NFO")


def normalize_expiry_date(value):
    if isinstance(value, datetime.datetime):
        return value.date()
    if isinstance(value, datetime.date):
        return value
    try:
        return datetime.date.fromisoformat(str(value))
    except Exception:
        return None


def get_index_option_expiry_map(index_name, underlying_names=None):
    today = get_today_ist()
    option_rows = []
    allowed_names = {str(item).strip().upper() for item in (underlying_names or []) if str(item).strip()}
    allowed_names.add(str(index_name or "").strip().upper())
    for row in get_nfo_instruments():
        row_name = str(row.get("name") or "").strip().upper()
        if row_name not in allowed_names:
            continue
        instrument_type = str(row.get("instrument_type") or "").upper()
        if instrument_type not in {"CE", "PE"}:
            continue
        expiry = normalize_expiry_date(row.get("expiry"))
        if not expiry or expiry < today:
            continue
        strike = float(row.get("strike") or 0)
        if strike <= 0:
            continue
        option_rows.append({**row, "expiry_date": expiry, "strike_value": strike})

    if not option_rows:
        return {}

    expiry_map = {}
    for row in option_rows:
        expiry_map.setdefault(row["expiry_date"], []).append(row)
    return expiry_map


def get_nearest_index_option_instruments(index_name, underlying_names=None):
    expiry_map = get_index_option_expiry_map(index_name, underlying_names=underlying_names)
    if not expiry_map:
        return []
    nearest_expiry = min(expiry_map.keys())
    return expiry_map.get(nearest_expiry, [])


def build_derivatives_expiry_nav(index_slug, available_expiries, selected_expiry, route_path):
    chips = []
    current_expiry = str(selected_expiry or "").strip()
    for expiry_value in available_expiries or []:
        label = f"Expiry {expiry_value[5:]}" if len(expiry_value) >= 10 else f"Expiry {expiry_value}"
        if expiry_value == current_expiry:
            label = f"{label} active"
        chips.append(
            {
                "label": label,
                "href": f"{route_path}?index={index_slug}&expiry={expiry_value}",
            }
        )
    return chips


def choose_comparison_expiry(available_expiries, selected_expiry):
    selected_date = normalize_expiry_date(selected_expiry)
    expiry_dates = [normalize_expiry_date(value) for value in (available_expiries or [])]
    expiry_dates = [value for value in expiry_dates if value]
    if not selected_date or len(expiry_dates) <= 1:
        return None

    later_dates = sorted(value for value in expiry_dates if value > selected_date)
    if later_dates:
        return later_dates[0].isoformat()

    earlier_dates = sorted((value for value in expiry_dates if value < selected_date), reverse=True)
    if earlier_dates:
        return earlier_dates[0].isoformat()
    return None


def build_cross_expiry_comparison(config, spot_value, selected_expiry, available_expiries, strike_span=None):
    comparison_expiry = choose_comparison_expiry(available_expiries, selected_expiry)
    if not comparison_expiry:
        return None

    comparison_chain = build_real_index_option_chain(
        config["index_name"],
        spot_value,
        config["strike_step"],
        underlying_names=config.get("underlying_names"),
        strike_span=strike_span if strike_span is not None else config.get("strike_span", 4),
        selected_expiry=comparison_expiry,
    )
    if not comparison_chain.get("available"):
        return {
            "comparison_expiry": comparison_expiry,
            "comparison_label": f"Compare vs {comparison_expiry}",
            "available": False,
            "error": comparison_chain.get("error") or "Comparison expiry data is unavailable right now.",
        }

    selected_label = str(selected_expiry or "Pending")
    comparison_label = str(comparison_chain.get("selected_expiry") or comparison_expiry)

    return {
        "available": True,
        "comparison_expiry": comparison_label,
        "comparison_label": f"{selected_label} vs {comparison_label}",
        "pcr_display": comparison_chain.get("pcr_display", "Pending"),
        "max_pain": comparison_chain.get("max_pain", "-"),
        "support_zone": comparison_chain.get("support_zone", "-"),
        "resistance_zone": comparison_chain.get("resistance_zone", "-"),
        "strongest_call_wall": comparison_chain.get("strongest_call_wall", "-"),
        "strongest_put_wall": comparison_chain.get("strongest_put_wall", "-"),
        "total_call_oi": comparison_chain.get("total_call_oi", "Pending"),
        "total_put_oi": comparison_chain.get("total_put_oi", "Pending"),
        "chain": comparison_chain,
    }


def summarize_strike_cluster(chain_rows, side_prefix, strike_step):
    numeric_key = f"{side_prefix}_oi_numeric"
    change_key = f"{side_prefix}_oi_change_numeric"
    valid_rows = [row for row in (chain_rows or []) if row.get(numeric_key) is not None]
    if not valid_rows:
        return {
            "band": "Pending",
            "dominant_strike": "-",
            "top_three": [],
            "change_bias": "Pending",
            "cluster_read": "Pending",
        }

    ranked_rows = sorted(valid_rows, key=lambda row: float(row.get(numeric_key) or 0), reverse=True)
    top_rows = ranked_rows[:3]
    dominant_row = top_rows[0]
    dominant_strike = int(float(dominant_row.get("strike") or 0)) if str(dominant_row.get("strike") or "").strip() else None
    strike_values = []
    for row in top_rows:
        try:
            strike_values.append(int(float(row.get("strike") or 0)))
        except Exception:
            continue
    band = "Pending"
    if strike_values:
        band = f"{min(strike_values)}-{max(strike_values)}"
    total_change = sum(float(row.get(change_key) or 0) for row in top_rows)
    change_bias = "Building"
    if total_change < 0:
        change_bias = "Cooling"
    elif total_change == 0:
        change_bias = "Flat"

    cluster_read = f"{side_prefix.title()} pressure is concentrated around {band}."
    if len(strike_values) >= 2 and max(strike_values) - min(strike_values) <= max(1, int(strike_step or 1)) * 2:
        cluster_read = f"{side_prefix.title()} pressure is tightly stacked around {band}."
    elif len(strike_values) >= 2:
        cluster_read = f"{side_prefix.title()} pressure is spread across {band}."

    return {
        "band": band,
        "dominant_strike": str(dominant_strike) if dominant_strike is not None else "-",
        "top_three": [str(value) for value in strike_values[:3]],
        "change_bias": change_bias,
        "cluster_read": cluster_read,
    }


def build_expiry_alert_signals(
    spot_value,
    strike_step,
    pcr_numeric,
    pcr_display,
    max_pain,
    support_zone,
    resistance_zone,
    premium_discount,
    call_cluster,
    put_cluster,
):
    alerts = []
    try:
        numeric_max_pain = float(max_pain)
    except Exception:
        numeric_max_pain = None
    try:
        numeric_support = float(support_zone)
    except Exception:
        numeric_support = None
    try:
        numeric_resistance = float(resistance_zone)
    except Exception:
        numeric_resistance = None

    if pcr_numeric is not None and pcr_numeric >= 1.20:
        alerts.append({
            "label": "Defensive Put Build",
            "value": pcr_display,
            "copy": f"PCR is elevated at {pcr_display}, which keeps put-side defense and squeeze risk on the watchlist.",
        })
    elif pcr_numeric is not None and pcr_numeric <= 0.80:
        alerts.append({
            "label": "Call Pressure Alert",
            "value": pcr_display,
            "copy": f"PCR is compressed at {pcr_display}, which keeps overhead call pressure and breakout failure risk in focus.",
        })

    if numeric_max_pain is not None and spot_value and abs(numeric_max_pain - float(spot_value)) <= max(1, int(strike_step or 1)):
        alerts.append({
            "label": "Pin Risk",
            "value": str(max_pain),
            "copy": f"Spot is sitting close to max pain near {max_pain}, so expiry pinning and slower range trade deserve attention.",
        })

    if numeric_support is not None and spot_value and abs(float(spot_value) - numeric_support) <= max(1, int(strike_step or 1)):
        alerts.append({
            "label": "Support Retest",
            "value": str(support_zone),
            "copy": f"Spot is close to the strongest put shelf near {support_zone}. A hold can trigger bounce attention; a break can accelerate downside pressure.",
        })

    if numeric_resistance is not None and spot_value and abs(numeric_resistance - float(spot_value)) <= max(1, int(strike_step or 1)):
        alerts.append({
            "label": "Resistance Test",
            "value": str(resistance_zone),
            "copy": f"Spot is close to the strongest call wall near {resistance_zone}. Traders should watch for either clean absorption or rejection.",
        })

    if call_cluster.get("change_bias") == "Building" and put_cluster.get("change_bias") == "Cooling":
        alerts.append({
            "label": "Overhead Pressure",
            "value": call_cluster.get("band"),
            "copy": f"Call-side clustering is building around {call_cluster.get('band')} while put support is cooling, which raises overhead pressure risk.",
        })
    elif put_cluster.get("change_bias") == "Building" and call_cluster.get("change_bias") == "Cooling":
        alerts.append({
            "label": "Support Reinforcement",
            "value": put_cluster.get("band"),
            "copy": f"Put-side clustering is building around {put_cluster.get('band')} while call pressure cools, which strengthens the support narrative.",
        })

    if premium_discount is not None and premium_discount > 0 and put_cluster.get("change_bias") == "Building":
        alerts.append({
            "label": "Carry + Support",
            "value": format_signed_price(premium_discount),
            "copy": "Futures premium and strengthening put-side support are aligned, which keeps constructive expiry carry on watch.",
        })
    elif premium_discount is not None and premium_discount < 0 and call_cluster.get("change_bias") == "Building":
        alerts.append({
            "label": "Discount Caution",
            "value": format_signed_price(premium_discount),
            "copy": "Futures are slipping into discount while call-side pressure builds, which is a caution signal for failed upside attempts.",
        })

    return alerts[:5]


def build_derivatives_watch_snapshot(index_slug, selected_expiry, host_root):
    config = DERIVATIVES_INDEX_CONFIG[index_slug]
    creds = get_active_kite_credentials()
    client = build_kite_client(with_access_token=True) if creds["api_key"] and creds["access_token"] else None
    spot_quote = fetch_index_quote_snapshot(client, config["quote_candidates"])
    spot_value = float((spot_quote or {}).get("last_price") or 0)
    chain = build_real_index_option_chain(
        config["index_name"],
        spot_value,
        config["strike_step"],
        underlying_names=config.get("underlying_names"),
        strike_span=8,
        selected_expiry=selected_expiry,
    )
    future_snapshot = get_live_index_future_snapshot(
        config["index_name"],
        underlying_names=config.get("underlying_names"),
    )
    chain_available = bool(chain.get("available"))
    future_available = bool(future_snapshot.get("available"))
    effective_expiry = chain.get("selected_expiry") or selected_expiry or future_snapshot.get("expiry_date") or "Pending"
    pcr_numeric = chain.get("pcr_numeric")
    pcr_display = chain.get("pcr_display", "Pending")
    max_pain = chain.get("max_pain", "-")
    support_zone = chain.get("support_zone", "-")
    resistance_zone = chain.get("resistance_zone", "-")
    call_cluster = summarize_strike_cluster(chain.get("rows") or [], "call", config["strike_step"])
    put_cluster = summarize_strike_cluster(chain.get("rows") or [], "put", config["strike_step"])
    premium_discount = None
    if future_available and future_snapshot.get("price_numeric") is not None and spot_value > 0:
        premium_discount = float(future_snapshot["price_numeric"]) - float(spot_value)
    alert_signals = build_expiry_alert_signals(
        spot_value,
        config["strike_step"],
        pcr_numeric,
        pcr_display,
        max_pain,
        support_zone,
        resistance_zone,
        premium_discount,
        call_cluster,
        put_cluster,
    )
    tone = get_pcr_interpretation(pcr_numeric)
    if max_pain not in {"-", "Pending"} and spot_value > 0:
        try:
            if abs(float(max_pain) - float(spot_value)) <= config["strike_step"]:
                tone = "Pin-risk structure"
        except Exception:
            pass
    status = "Live"
    if not chain_available:
        status = "Chain Pending"
    elif not future_available:
        status = "Futures Pending"
    return {
        "watch_key": f"{index_slug}:{effective_expiry}",
        "index_slug": index_slug,
        "index_label": "Nifty 50" if index_slug == "nifty-options" else "Bank Nifty",
        "expiry": effective_expiry,
        "spot": format_price(spot_value) if spot_value > 0 else "Pending",
        "pcr": pcr_display,
        "max_pain": str(max_pain),
        "tone": tone,
        "pressure_bands": f"C {call_cluster.get('band')} / P {put_cluster.get('band')}",
        "alert_count": len(alert_signals),
        "top_alert": alert_signals[0]["label"] if alert_signals else "No active alert",
        "top_alert_copy": alert_signals[0]["copy"] if alert_signals else "No high-priority expiry watch alert is active right now.",
        "status": status,
        "dashboard_url": f"{host_root.rstrip('/')}/derivatives/expiry-strategy?index={index_slug}&expiry={effective_expiry}" if effective_expiry and effective_expiry != "Pending" else f"{host_root.rstrip('/')}/derivatives/expiry-strategy?index={index_slug}",
        "chain_url": f"{host_root.rstrip('/')}/derivatives/index/option-chain?index={index_slug}&expiry={effective_expiry}" if effective_expiry and effective_expiry != "Pending" else f"{host_root.rstrip('/')}/derivatives/index/option-chain?index={index_slug}",
        "remove_url": f"{host_root.rstrip('/')}/admin/derivatives/watchlist/remove?index={index_slug}&expiry={effective_expiry}",
        "alerts": alert_signals,
        "market_error": (None if chain_available else chain.get("error")) or (None if future_available else future_snapshot.get("error")),
    }


def build_derivatives_watchlist_context(host_root):
    state = load_derivatives_watchlist_state()
    rows = []
    for entry in state.get("entries") or []:
        rows.append(build_derivatives_watch_snapshot(entry["index_slug"], entry["expiry"], host_root))

    live_rows = [row for row in rows if row.get("status") == "Live"]
    total_alerts = sum(int(row.get("alert_count") or 0) for row in rows)
    highest_alert_row = max(rows, key=lambda row: int(row.get("alert_count") or 0), default=None)
