@app.route("/stocks/equity-stock-page")
def equity_stock_page():
    raw_symbols = request.args.get("symbols", ",".join(DEFAULT_SYMBOLS))
    raw_date = request.args.get("date", get_today_ist().isoformat())
    raw_start = request.args.get("start", DEFAULT_START)
    raw_end = request.args.get("end", DEFAULT_END)
    raw_interval = request.args.get("interval", str(DEFAULT_EQUITY_OHLC_INTERVAL))

    error = None
    results = []

    try:
        symbols = parse_symbol_list(raw_symbols)
        selected_date = parse_date(raw_date)
        start_time = parse_time(raw_start, DEFAULT_START)
        end_time = parse_time(raw_end, DEFAULT_END)
        interval_minutes = int(str(raw_interval or DEFAULT_EQUITY_OHLC_INTERVAL).strip())

        if not symbols:
            raise ValueError("Please provide at least one NSE symbol.")
        creds = get_active_kite_credentials()
        if not creds["api_key"] or not creds["access_token"]:
            raise ValueError("Kite API key or access token is missing in .env.")
        if end_time <= start_time:
            raise ValueError("End time must be after start time.")
        if interval_minutes not in EQUITY_OHLC_INTERVAL_OPTIONS:
            raise ValueError("Please choose a supported candle interval.")

        results, missing = get_equity_ohlc(symbols, selected_date, start_time, end_time, interval_minutes=interval_minutes)
        if missing:
            missing_text = ", ".join(missing)
            error = f"Could not find NSE equity symbols: {missing_text}"
    except Exception as exc:
        symbols = parse_symbol_list(raw_symbols) or DEFAULT_SYMBOLS
        selected_date = raw_date
        start_time = raw_start
        end_time = raw_end
        interval_minutes = DEFAULT_EQUITY_OHLC_INTERVAL
        error = str(exc)

    canonical_query = urllib.parse.urlencode(
        {
            "symbols": ",".join(symbols),
            "date": selected_date if isinstance(selected_date, str) else selected_date.isoformat(),
            "start": start_time if isinstance(start_time, str) else start_time.strftime("%H:%M"),
            "end": end_time if isinstance(end_time, str) else end_time.strftime("%H:%M"),
            "interval": interval_minutes,
        }
    )
    canonical_url = f"{request.url_root.rstrip('/')}/stocks/equity-stock-page?{canonical_query}"
    seo_title = f"NSE Equity OHLC Scanner ({interval_minutes} Min) | TraderHub"
    seo_description = f"Track {', '.join(symbols[:3])} and other NSE stocks with {interval_minutes}-minute OHLC candles, opening range levels, and intraday snapshot context on TraderHub."

    return render_template_string(
        PAGE_TEMPLATE,
        results=results,
        error=error,
        symbols=symbols,
        request_symbols=raw_symbols,
        selected_date=selected_date if isinstance(selected_date, str) else selected_date.isoformat(),
        today_date=get_today_ist().isoformat(),
        yesterday_date=get_yesterday_ist().isoformat(),
        start_time=start_time if isinstance(start_time, str) else start_time.strftime("%H:%M"),
        end_time=end_time if isinstance(end_time, str) else end_time.strftime("%H:%M"),
        selected_interval=interval_minutes,
        interval_options=EQUITY_OHLC_INTERVAL_OPTIONS,
        seo_title=seo_title,
        seo_description=seo_description,
        canonical_url=canonical_url,
        **build_public_ad_context("NSE Equity OHLC Scanner", page_family="scanner"),
    )


