def fetch_internal_seo_page_snapshot(page_row):
    with app.test_client() as client:
        response = client.get(
            page_row["path"],
            base_url=f"https://{page_row['domain']}",
            follow_redirects=True,
        )
    html_text = response.get_data(as_text=True)
    snapshot = extract_seo_snapshot_from_html(
        html_text,
        fallback_url=page_row["url"],
    )
    snapshot["status_code"] = response.status_code
    snapshot["last_checked_at"] = utcnow_iso()
    return snapshot


def fetch_internal_seo_page_render(page_row):
    with app.test_client() as client:
        response = client.get(
            page_row["path"],
            base_url=f"https://{page_row['domain']}",
            follow_redirects=True,
        )
    return {
        "status_code": response.status_code,
        "html_text": response.get_data(as_text=True),
        "final_path": response.request.path if getattr(response, "request", None) else page_row["path"],
        "final_url": page_row["url"],
    }


def extract_news_page_snapshot_from_html(page_row, html_text):
    href_matches = re.findall(r'<a[^>]+href=["\'](.*?)["\']', html_text or "", flags=re.IGNORECASE)
    internal_hrefs = [
        href
        for href in href_matches
        if href.startswith("/")
        or href.startswith(f"https://{page_row['domain']}/")
        or href.startswith("https://traderhub.in/")
    ]
    stock_links = {
        href
        for href in internal_hrefs
        if "/stocks/" in href
    }
    story_links = {
        href
        for href in internal_hrefs
        if any(
            token in href
            for token in (
                "/stocks/",
                "/market/archive/",
                "/market/trends/",
                "/sectors/",
            )
        )
    }
    section_count = len(re.findall(r"<section\b", html_text or "", flags=re.IGNORECASE))
    article_count = len(re.findall(r"<article\b", html_text or "", flags=re.IGNORECASE))
    heading_count = len(re.findall(r"<h2\b", html_text or "", flags=re.IGNORECASE))
    bullet_count = len(re.findall(r"<li\b", html_text or "", flags=re.IGNORECASE))
    text_content = _clean_extracted_html_text(html_text or "").lower()
    summary_present = bool(
        re.search(
            r"\b(editor summary|market summary|sector summary|stock summary|trend summary|archive summary|key takeaways|what matters)\b",
            text_content,
            flags=re.IGNORECASE,
        )
    )
    fallback_active = bool(
        re.search(
            r"\b(source pending|waiting for a stronger|placeholder|temporarily unavailable|safe fallback|fallback mode|fallback view)\b",
            text_content,
            flags=re.IGNORECASE,
        )
    )
    market_error_present = bool(
        re.search(
            r"\b(market error|could not build a reliable market snapshot|unable to complete|source unavailable)\b",
            text_content,
            flags=re.IGNORECASE,
        )
    )
    shell_only = bool(
        len(story_links) == 0
        and len(stock_links) == 0
        and (section_count + article_count + heading_count) <= 3
        and bullet_count <= 2
    )
    notes = []
    if fallback_active:
        notes.append("fallback-copy")
    if market_error_present:
        notes.append("market-error")
    if shell_only:
        notes.append("shell-only")
    return {
        "story_link_count": len(story_links),
        "stock_link_count": len(stock_links),
        "section_count": section_count + article_count + heading_count,
        "bullet_count": bullet_count,
        "summary_present": summary_present,
        "fallback_active": fallback_active,
        "market_error_present": market_error_present,
        "shell_only": shell_only,
        "checked_at": utcnow_iso(),
        "notes": ", ".join(notes),
    }


def extract_internal_links_from_html(html_text, fallback_url=""):
    if not html_text:
        return []
    href_matches = re.findall(r'<a[^>]+href=["\'](.*?)["\']', html_text, flags=re.IGNORECASE)
    allowed_domains = {"traderhub.in", "app.traderhub.in", "bot.traderhub.in"}
    links = []
    seen = set()
    for href in href_matches:
        raw_href = str(href or "").strip()
        if (
            not raw_href
            or raw_href.startswith("#")
            or raw_href.lower().startswith(("javascript:", "mailto:", "tel:"))
        ):
            continue
        absolute_url = urllib.parse.urljoin(fallback_url, raw_href)
        parsed = urllib.parse.urlparse(absolute_url)
        if parsed.scheme not in ("http", "https") or parsed.netloc.lower() not in allowed_domains:
            continue
        normalized_url = urllib.parse.urlunparse(
            (
                parsed.scheme,
                parsed.netloc.lower(),
                parsed.path or "/",
                "",
                parsed.query,
                "",
            )
        )
        if normalized_url in seen:
            continue
        seen.add(normalized_url)
        links.append({"to_url": normalized_url, "link_type": "internal"})
    return links


def run_seo_metadata_extract(limit=100, domain=None, only_missing=False, profile="safe"):
    check_id = start_check(
        "metadata_extract",
        notes=f"Metadata extraction run | domain={domain or 'all'} | limit={limit} | profile={profile}",
    )
    pages_scanned = 0
    failures = 0
    try:
        profile_map = get_seo_extractor_profiles()
        selected_page_types = profile_map.get(profile, profile_map["safe"])
        page_rows = fetch_seo_pages_for_extraction(
            domain=domain,
            limit=limit,
            only_missing=only_missing,
            page_types=selected_page_types or None,
        )
        for page_row in page_rows:
            try:
                snapshot = fetch_internal_seo_page_snapshot(page_row)
            except BaseException as exc:
                failures += 1
                snapshot = {
                    "title": "",
                    "meta_description": "",
                    "h1": "",
                    "canonical_url": page_row["url"],
                    "robots_directive": page_row.get("robots_directive") or "",
                    "index_status": page_row.get("index_status") or page_row.get("index_expected") or "noindex",
                    "status_code": 500,
                    "schema_type": page_row.get("schema_type") or "WebPage",
                    "last_checked_at": utcnow_iso(),
                }
            update_seo_page_snapshot(page_row["id"], snapshot)
            pages_scanned += 1
        finish_check(
            check_id,
            "completed",
            pages_scanned=pages_scanned,
            issues_found=failures,
            notes=f"Completed metadata extraction for {pages_scanned} pages with {failures} failures.",
        )
        summary = get_extraction_summary()
        summary["pages_scanned"] = pages_scanned
        summary["failures"] = failures
        summary["domain"] = domain or "all"
        summary["only_missing"] = bool(only_missing)
        summary["profile"] = profile
        summary["page_types"] = selected_page_types
        return summary
    except BaseException as exc:
        finish_check(
            check_id,
            "failed",
            pages_scanned=pages_scanned,
            issues_found=failures,
            notes=f"Metadata extraction failed: {exc}",
        )
        raise


