def refresh_seo_snapshot_for_url(url):
    page_row = fetch_seo_page_by_url(url)
    if not page_row:
        raise ValueError(f"SEO page record not found for {url}")
    snapshot = fetch_internal_seo_page_snapshot(page_row)
    update_seo_page_snapshot(page_row["id"], snapshot)
    refreshed_row = fetch_seo_page_by_url(url) or {}
    return {"page": refreshed_row, "snapshot": snapshot}


def refresh_seo_snapshots_for_issue_type(issue_type=None, limit=25):
    page_rows = fetch_active_issue_pages(issue_type=issue_type, limit=limit)
    refreshed = []
    failures = []
    for page_row in page_rows:
        try:
            payload = refresh_seo_snapshot_for_url(page_row["url"])
            refreshed.append(payload["page"]["url"])
        except BaseException as exc:
            failures.append({"url": page_row["url"], "message": str(exc), "error_type": type(exc).__name__})
    return {
        "issue_type": issue_type or "all",
        "requested_limit": limit,
        "refreshed_count": len(refreshed),
        "refreshed_urls": refreshed,
        "failures": failures,
    }


def get_news_snapshot_profiles():
    return {
        "summary-core": ["trend", "archive", "sector_archive"],
        "summary-wide": ["trend", "archive", "sector_archive", "stock_archive", "stock_news"],
        "summary-live": ["market_news", "alerts_prep"],
        "summary-balance": ["market_news", "alerts_prep", "trend", "archive", "sector_archive", "stock_archive", "stock_news"],
        "summary-full": [],
    }


def run_news_snapshot_scan(limit=40, domain=None, profile="summary-core", offset=0, only_missing=True):
    profile_map = get_news_snapshot_profiles()
    requested_limit = int(limit)
    close_stale_running_checks("news_snapshot_scan", older_than_minutes=3, status="timed_out")
    if profile == "summary-live":
        effective_limit = min(requested_limit, 6)
    elif profile == "summary-balance":
        effective_limit = min(requested_limit, 12)
    elif profile == "summary-full":
        effective_limit = min(requested_limit, 8)
    else:
        effective_limit = min(requested_limit, 10)
    selected_page_types = profile_map.get(profile, profile_map["summary-core"])
    check_id = start_check(
        "news_snapshot_scan",
        notes=(
            f"News snapshot scan | domain={domain or 'all'} | "
            f"limit={requested_limit} | effective_limit={effective_limit} | "
            f"offset={offset} | profile={profile} | only_missing={int(bool(only_missing))}"
        ),
    )
    try:
        page_rows = fetch_news_pages_for_snapshot_scan(
            domain=domain,
            limit=effective_limit,
            offset=offset,
            page_types=selected_page_types or None,
            only_missing=only_missing,
        )
        failures = []
        for page_row in page_rows:
            try:
                render_payload = fetch_internal_seo_page_render(page_row)
                snapshot = extract_news_page_snapshot_from_html(page_row, render_payload.get("html_text", ""))
                upsert_news_page_snapshot(page_row, snapshot)
            except BaseException as exc:
                failures.append({"url": page_row["url"], "message": str(exc), "error_type": type(exc).__name__})
        finish_check(
            check_id,
            "completed",
            pages_scanned=len(page_rows),
            issues_found=len(failures),
            notes=f"News snapshot scan completed for {len(page_rows)} pages with {len(failures)} failures.",
        )
        summary = get_news_snapshot_run_summary()
        summary.update(
            {
                "status": "ok",
                "domain": domain or "all",
                "profile": profile,
                "requested_limit": requested_limit,
                "effective_limit": effective_limit,
                "offset": int(offset),
                "only_missing": bool(only_missing),
                "pages_scanned": len(page_rows),
                "failures": failures,
            }
        )
        return summary
    except BaseException as exc:
        finish_check(
            check_id,
            "failed",
            pages_scanned=0,
            issues_found=0,
            notes=f"News snapshot scan failed: {exc}",
        )
        raise


def run_seo_crawlability_scan(limit=100, domain=None, profile="graph-core", offset=0, only_unlinked=True):
    requested_limit = int(limit)
    effective_limit = requested_limit
    if profile == "full":
        effective_limit = min(requested_limit, 30 if only_unlinked else 8)
    elif profile == "graph-wide":
        effective_limit = min(requested_limit, 35 if only_unlinked else 10)
    elif profile == "graph-core":
        effective_limit = min(requested_limit, 40 if only_unlinked else 12)
    elif profile == "public-plus":
        effective_limit = min(requested_limit, 40 if only_unlinked else 12)
    else:
        effective_limit = min(requested_limit, 60 if only_unlinked else 12)
    check_id = start_check(
        "crawlability_scan",
        notes=f"Crawlability link scan | domain={domain or 'all'} | limit={effective_limit} | offset={offset} | profile={profile} | only_unlinked={int(bool(only_unlinked))}",
    )
    pages_scanned = 0
    failures = 0
    total_links = 0
    failure_messages = []
    try:
        profile_map = get_seo_extractor_profiles()
        selected_page_types = profile_map.get(profile, profile_map["public-plus"])
        remaining_before = count_seo_pages_for_link_scan(
            domain=domain,
            page_types=selected_page_types or None,
            only_checked=True,
            only_unlinked=only_unlinked,
        )
        page_rows = fetch_seo_pages_for_link_scan(
            domain=domain,
            limit=effective_limit,
            offset=offset,
            only_checked=True,
            page_types=selected_page_types or None,
            only_unlinked=only_unlinked,
        )
        for page_row in page_rows:
            try:
                render_data = fetch_internal_seo_page_render(page_row)
                links = extract_internal_links_from_html(
                    render_data["html_text"],
                    fallback_url=page_row["url"],
                )
                replace_page_crawl_links(page_row["id"], page_row["url"], links)
                pages_scanned += 1
                total_links += len(links)
            except BaseException as exc:
                failures += 1
                failure_messages.append(f"{page_row['url']}: {type(exc).__name__}: {exc}")
        finish_check(
            check_id,
            "completed" if failures == 0 else "completed_with_warnings",
            pages_scanned=pages_scanned,
            issues_found=failures,
            notes="; ".join(failure_messages[:5]),
        )
        return {
            "status": "ok",
            "domain": domain or "all",
            "profile": profile,
            "requested_limit": requested_limit,
            "effective_limit": effective_limit,
            "offset": offset,
            "only_unlinked": bool(only_unlinked),
            "remaining_before": remaining_before,
            "remaining_after": max(0, remaining_before - pages_scanned),
            "pages_scanned": pages_scanned,
            "total_links": total_links,
            "failures": failures,
            "summary": get_crawlability_overview(limit=100),
        }
    except BaseException as exc:
        finish_check(
            check_id,
            "failed",
            pages_scanned=pages_scanned,
            issues_found=failures,
            notes=f"{type(exc).__name__}: {exc}",
        )
        raise


def _format_sitemap_lastmod(value):
    if not value:
        return get_today_ist().isoformat()
    try:
        return datetime.datetime.fromisoformat(str(value)).date().isoformat()
    except Exception:
        return get_today_ist().isoformat()


def _build_sitemap_xml(url_rows):
    lines = ['<?xml version="1.0" encoding="UTF-8"?>', '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">']
    for row in url_rows:
        lines.append("  <url>")
        lines.append(f"    <loc>{html_lib.escape(row['url'])}</loc>")
        lines.append(f"    <lastmod>{_format_sitemap_lastmod(row.get('last_checked_at'))}</lastmod>")
        lines.append("  </url>")
    lines.append("</urlset>")
    return "\n".join(lines)


def _build_sitemap_index_xml(sitemap_entries):
    lines = ['<?xml version="1.0" encoding="UTF-8"?>', '<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">']
    for entry in sitemap_entries:
        lines.append("  <sitemap>")
        lines.append(f"    <loc>{html_lib.escape(entry['public_url'])}</loc>")
        lines.append(f"    <lastmod>{_format_sitemap_lastmod(entry.get('last_generated_at'))}</lastmod>")
        lines.append("  </sitemap>")
    lines.append("</sitemapindex>")
    return "\n".join(lines)


def run_seo_sitemap_generation():
    check_id = start_check("sitemap_build", notes="Generate sitemap XML from eligible public SEO pages")
    try:
        eligible_pages = fetch_sitemap_eligible_pages()
        grouped = {}
        for row in eligible_pages:
            grouped.setdefault(row["sitemap_group"], []).append(row)

        SITEMAP_DIR.mkdir(parents=True, exist_ok=True)
        generated_at = utcnow_iso()
        sitemap_rows = []
        for sitemap_group, rows in sorted(grouped.items()):
            sitemap_name = f"{sitemap_group}.xml"
            file_path = SITEMAP_DIR / sitemap_name
            public_url = f"https://traderhub.in/sitemaps/{sitemap_name}"
            file_path.write_text(_build_sitemap_xml(rows), encoding="utf-8")
            sitemap_rows.append(
                {
                    "sitemap_name": sitemap_name,
                    "domain": "traderhub.in",
                    "sitemap_type": sitemap_group,
                    "file_path": str(file_path),
                    "public_url": public_url,
                    "url_count": len(rows),
                    "last_generated_at": generated_at,
                    "status": "completed",
                    "notes": f"Generated from {len(rows)} eligible public URLs.",
                }
            )

        index_path = SITEMAP_DIR / "sitemap.xml"
        index_public_url = "https://traderhub.in/sitemap.xml"
        index_path.write_text(_build_sitemap_index_xml(sitemap_rows), encoding="utf-8")
        sitemap_rows.insert(
            0,
            {
                "sitemap_name": "sitemap.xml",
                "domain": "traderhub.in",
                "sitemap_type": "index",
                "file_path": str(index_path),
                "public_url": index_public_url,
                "url_count": len(sitemap_rows),
                "last_generated_at": generated_at,
                "status": "completed",
                "notes": "Top-level sitemap index for TraderHub public SEO pages.",
            },
        )

        replace_sitemap_records(sitemap_rows)
        finish_check(
            check_id,
            "completed",
            pages_scanned=len(eligible_pages),
            issues_found=0,
            notes=f"Generated {len(sitemap_rows)} sitemap files from {len(eligible_pages)} pages.",
        )
        return {
            "generated_files": len(sitemap_rows),
            "eligible_pages": len(eligible_pages),
            "groups": {group: len(rows) for group, rows in sorted(grouped.items())},
            "records": sitemap_rows,
        }
    except BaseException as exc:
        finish_check(
            check_id,
            "failed",
            pages_scanned=0,
            issues_found=0,
            notes=f"Sitemap generation failed: {exc}",
        )
        raise


