@app.route("/admin/derivatives/delivery/trigger")
def derivatives_delivery_trigger():
    profile_key = str(request.args.get("profile", "") or "").strip().lower()
    payload = build_derivatives_delivery_payload(request.url_root.rstrip("/"), profile_key)
    if not payload:
        return jsonify({"status": "error", "message": "Please provide a valid delivery profile."}), 400
    if payload["channel"] == "telegram":
        try:
            telegram_response = send_telegram_message(payload["body"])
            payload["trigger_status"] = "sent"
            payload["trigger_message"] = "Telegram delivery sent successfully."
            payload["transport_response"] = telegram_response
        except Exception as exc:
            payload["trigger_status"] = "transport_error"
            payload["trigger_message"] = f"Telegram delivery failed: {exc}"
    else:
        payload["trigger_status"] = "preview_only"
        payload["trigger_message"] = (
            f"{payload['channel_label']} delivery is not wired to an external transport yet. "
            "This trigger confirms the live payload that would be sent right now."
        )
    append_derivatives_delivery_history(payload, mode="manual")
    state = load_derivatives_delivery_profiles()
    for profile in state.get("profiles") or []:
        if profile.get("key") == profile_key:
            apply_derivatives_delivery_result(profile, payload)
            break
    save_derivatives_delivery_profiles(state)
    return jsonify(payload)


@app.route("/admin/derivatives/delivery/retry-last-failure")
def derivatives_delivery_retry_last_failure():
    profile_key = str(request.args.get("profile", "") or "").strip().lower()
    if not profile_key:
        return jsonify({"status": "error", "message": "Please provide a valid delivery profile."}), 400
    state = load_derivatives_delivery_profiles()
    target_profile = next((profile for profile in (state.get("profiles") or []) if profile.get("key") == profile_key), None)
    if not target_profile:
        return jsonify({"status": "error", "message": "Please provide a valid delivery profile."}), 400
    latest_failure = get_derivatives_delivery_latest_failure(profile_key)
    if not latest_failure:
        return jsonify({"status": "error", "message": "No failed delivery is currently logged for that profile."}), 404
    payload = trigger_derivatives_delivery_profile(target_profile, request.url_root.rstrip("/"))
    payload["retry_of"] = latest_failure.get("logged_at")
    payload["retry_previous_status"] = latest_failure.get("trigger_status")
    append_derivatives_delivery_history(payload, mode="retry")
    apply_derivatives_delivery_result(target_profile, payload)
    save_derivatives_delivery_profiles(state)
    return jsonify(payload)


@app.route("/admin/derivatives/delivery/run-due")
def derivatives_delivery_run_due():
    state = load_derivatives_delivery_profiles()
    results = []
    due_count = 0
    sent_count = 0
    skipped_backoff = 0
    for profile in state.get("profiles") or []:
        schedule_status = get_profile_schedule_status(profile)
        if schedule_status["backoff_active"]:
            skipped_backoff += 1
            results.append(
                {
                    "profile": profile.get("key"),
                    "name": profile.get("name"),
                    "channel": profile.get("channel"),
                    "trigger_status": "backoff_active",
                    "trigger_message": schedule_status["next_run_label"],
                    "alert_total": 0,
                    "row_count": 0,
                }
            )
            continue
        if not schedule_status["due_now"]:
            continue
        due_count += 1
        payload = trigger_derivatives_delivery_profile(profile, request.url_root.rstrip("/"))
        append_derivatives_delivery_history(payload, mode="scheduled")
        apply_derivatives_delivery_result(profile, payload)
        if payload.get("trigger_status") in {"sent", "preview_only"}:
            sent_count += 1
        results.append(
            {
                "profile": profile.get("key"),
                "name": profile.get("name"),
                "channel": profile.get("channel"),
                "trigger_status": payload.get("trigger_status"),
                "trigger_message": payload.get("trigger_message"),
                "alert_total": payload.get("alert_total"),
                "row_count": payload.get("row_count"),
            }
        )
    save_derivatives_delivery_profiles(state)
    return jsonify(
        {
            "status": "ok",
            "due_profiles": due_count,
            "completed_profiles": sent_count,
            "skipped_backoff_profiles": skipped_backoff,
            "results": results,
            "checked_at": utcnow_iso(),
        }
    )


